"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7027],{9340(e){e.exports=JSON.parse('{"title":"12\ub144\uac04\uc758 PostCSS \uad00\ub9ac, \uadf8\ub9ac\uace0 \uad50\ud6c8","date":"2025-08-27","coverUrl":"/kudzu-based-bench/assets/notion/1781d635012cbe8b.png","html":"<h1 data-notion-block-id=\\"256e548d-8a8e-80e1-8bf4-fac3ad68e383\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"256e548d-8a8e-8035-aa8f-f3917c1647a7\\" id=\\"256e548d-8a8e-8035-aa8f-f3917c1647a7\\">12\ub144\uac04\uc758 PostCSS \uad00\ub9ac, \uadf8\ub9ac\uace0 \uad50\ud6c8</h2><a href=\\"https://evilmartians.com/chronicles/what-we-learned-from-creating-postcss\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/what-we-learned-from-creating-postcss</a><p data-notion-block-id=\\"256e548d-8a8e-8029-b3f0-ecb6adc6d4bc\\">\ub9ce\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\ub4e4\uc5d0\uac8c PostCSS\ub97c \ub9cc\ub4e4\uace0, \uad00\ub9ac\ud558\ub294\ub370\uc5d0\uc11c \ubc30\uc6b4 \uad50\ud6c8\uc744 \uc801\uc740 \uae00\uc785\ub2c8\ub2e4. \ub2e4\uc591\ud55c \uad50\ud6c8\uc774 \ub4e4\uc5b4\uc788\uc5b4, \uc0ac\ub0b4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4 \ub54c\uc5d0\ub3c4, \uc790\uc2e0\ub9cc\uc758 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4 \ub54c\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub418\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/298d028d-8e9c-4d13-b87a-3ae9f00712fa#35e95bc9-114c-4463-ad51-9b7ff5bf97dd\\">\uc624\ud508\uc18c\uc2a4 \uad00\ub9ac\uc790\ub85c\ubd80\ud130 \ubc30\uc6b8 \uc218 \uc788\ub294 \uc810</a>\ub3c4 \uc88b\uc740 \uae00\uc774\ub2c8 \ud55c \ubc88 \ubcf4\uc138\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"256e548d-8a8e-806c-b334-f33e0cb67f42\\" id=\\"256e548d-8a8e-806c-b334-f33e0cb67f42\\">React cache, \uadf8\ub9ac\uace0 \ub370\uc774\ud130 \uc77c\uad00\uc131</h2><a href=\\"https://twofoldframework.com/blog/react-cache-its-about-consistency\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://twofoldframework.com/blog/react-cache-its-about-consistency</a><p data-notion-block-id=\\"256e548d-8a8e-80f8-aea1-c2b4aa93b71d\\">React\uc758 <code>cache()</code>\uac00 \ub2e8\uc21c\ud788 <code>memo()</code>\uc758 \ud655\uc7a5\ub41c \ubc84\uc804, \ucd5c\uc801\ud654 \ubc29\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \ub354 \ub9ce\uc740 \uac83\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 cache\ub85c \uac10\uc2fc \uacbd\uc6b0\uc758 \ub370\uc774\ud130 \uc77c\uad00\uc131\uc5d0 \ub300\ud574 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c, \ub3d9\uc2dc\uc131\uc758 tearing \ud604\uc0c1\uc744 \uc0b4\ud3b4\ubcf4\uc2dc\ub824\uba74, <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\">React 18\uc5d0\uc11c\uc758 \uc0c1\ud0dc \ubd88\uc77c\uce58 \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"259e548d-8a8e-80c2-8100-c4d0120a11fd\\" id=\\"259e548d-8a8e-80c2-8100-c4d0120a11fd\\">\ub0b4 \ud398\uc774\uc9c0\uc758 Baseline \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://web.dev/blog/whats-my-baseline\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/blog/whats-my-baseline</a><p data-notion-block-id=\\"259e548d-8a8e-80b2-96b4-e4c8c6038639\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c3e548d-8a8e-80a7-9539-cddcd66b5f38#1c3e548d-8a8e-80a6-9815-e96b1f1b8eb0\\">Baseline</a>\uc758 \uae30\uc900\uc744 \uc5b4\ub514\ub85c \ub9de\ucdb0\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uacfc \uc5b4\ub5a4 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uc5f0\uacb0\ub41c \uae00(<a href=\\"https://web.dev/articles/how-to-choose-your-baseline-target\\">target\uc744 \uc120\ud0dd\ud558\ub294 \ubc29\ubc95</a>)\uc740 Baseline\uc744 \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"259e548d-8a8e-803b-94cd-c89be636be89\\" id=\\"259e548d-8a8e-803b-94cd-c89be636be89\\">CSS Reset\uc740 \uc5c6\ub2e4.</h2><a href=\\"https://aaadaaam.com/notes/useful-defaults/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aaadaaam.com/notes/useful-defaults/</a><p data-notion-block-id=\\"259e548d-8a8e-804f-a11b-cd8d80a9de60\\">\uc6b0\ub9ac\ub294 \ud754\ud788 \ube0c\ub77c\uc6b0\uc800 \uc2a4\ud0c0\uc77c\uc744 \uc5c6\uc560\uae30 \uc704\ud574 \'CSS Reset\'\uc744 \uc0ac\uc6a9\ud558\uc9c0\ub9cc, \uc774\uac83\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc744 \ub54c\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uae30\uc874 CSS Reset \ubc29\uc2dd\uc758 \ubb38\uc81c\uc810\uc744 \uc9da\uc5b4\ubcf4\uace0, \ub354 \ub098\uc740 \ub300\uc548\uc73c\ub85c \ubc1c\uc804\ud574 \uc628 \uacfc\uc815\uc744 \uba85\ud655\ud558\uac8c \uc18c\uac1c\ud574 \uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"259e548d-8a8e-8042-bfc4-d1ef4d79191c\\" id=\\"259e548d-8a8e-8042-bfc4-d1ef4d79191c\\">React \ucee4\ubba4\ub2c8\ud2f0\ub294 \uc5b4\ub514\ub85c \uac00\ub294\uac00</h2><a href=\\"https://leerob.com/reflections\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://leerob.com/reflections</a><p data-notion-block-id=\\"256e548d-8a8e-8041-a905-c0e67879dc22\\">React\uac00 Next.js\uc640 \uacb0\ud569\uc744 \uc911\uc694\uc2dc\ud55c \uc774\uc720, \uadf8\ub9ac\uace0 \ud53c\ub4dc\ubc31\uacfc OSS\ubb38\uc81c\ub97c \uadf8\ub3d9\uc548 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud574\uc654\ub294\uc9c0, \uadf8\ub9ac\uace0 RSC\uc5d0 \ub300\ud55c \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc788\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc218\ub9ce\uc740 Next.js\uc5d0 \ub300\ud55c \ube44\ud310\uacfc \ube44\ub09c\ub4e4\uc774 \uc788\uc5b4\uc654\ub294\ub370, \uc65c React\uac00, \uadf8\ub9ac\uace0 Next.js\uac00 \uadf8\ub7f0 \uc120\ud0dd\uc744 \ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc9c0\uae08\uc740 \uc5b4\ub5bb\uac8c \ud758\ub7ec\uac00\uace0 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e4\uc74c\ubd80\ud130\ub294 \ub2f4\ub860\uc5d0 \ucc38\uc5ec\ud558\uae30 \ubcf4\ub2e4\ub294, \uc5b4\ub5bb\uac8c \ubc1c\uc804\ud558\uace0 \uc2f6\uae30\uc5d0 \uc774\ub7f0 \uc120\ud0dd\uc744 \ud588\ub294\uc9c0 \ube44\ud310\uc801\uc73c\ub85c \ubc14\ub77c\ubcf4\ub294 \uc2dc\uac01\uc774 \ud544\uc694\ud558\uaca0\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"256e548d-8a8e-8018-afc9-c49241df84b3\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"25ce548d-8a8e-80f7-8a8d-e3a0dba6c6e8\\" id=\\"25ce548d-8a8e-80f7-8a8d-e3a0dba6c6e8\\"><code>Intl.</code>API\uc758 \uac15\ub825\ud568</h2><a href=\\"https://www.smashingmagazine.com/2025/08/power-intl-api-guide-browser-native-internationalization/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/08/power-intl-api-guide-browser-native-internationalization/</a><p data-notion-block-id=\\"25ce548d-8a8e-8097-a087-ebd453e8ac61\\"><code>Intl</code>API\ub294 \ubb34\uc5c7\uc774 \uc788\uace0, \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"259e548d-8a8e-80c4-9241-d5e5e46f5cc1\\" id=\\"259e548d-8a8e-80c4-9241-d5e5e46f5cc1\\">localStorage\ub294 \uc5b8\uc81c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uac00</h2><a href=\\"https://www.developerway.com/posts/local-storage-instead-of-context\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/local-storage-instead-of-context</a><h2 data-notion-block-id=\\"259e548d-8a8e-803a-8520-f0f654b80fa1\\" id=\\"259e548d-8a8e-803a-8520-f0f654b80fa1\\">SVG <code>&#x3C;path></code> \uc778\ud130\ub809\ud2f0\ube0c \uac00\uc774\ub4dc</h2><a href=\\"https://www.joshwcomeau.com/svg/interactive-guide-to-paths/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/svg/interactive-guide-to-paths/</a><h2 data-notion-block-id=\\"256e548d-8a8e-80ce-82ed-d49f4a2c4833\\" id=\\"256e548d-8a8e-80ce-82ed-d49f4a2c4833\\">\uac04\ub2e8\ud558\uac8c \uc54c\uc544\ubcf4\ub294 \uc131\ub2a5 \ud301</h2><a href=\\"https://www.debugbear.com/blog/fix-slow-loading-websites\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/fix-slow-loading-websites</a><h2 data-notion-block-id=\\"259e548d-8a8e-80c9-ab9f-c24571185ddc\\" id=\\"259e548d-8a8e-80c9-ab9f-c24571185ddc\\">RN Node-API\uac00 \ub3d9\uc791\ud558\ub294 \ubc29\ubc95 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.callstack.com/blog/how-node-api-works-in-react-native-a-deep-dive\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/how-node-api-works-in-react-native-a-deep-dive</a><p data-notion-block-id=\\"256e548d-8a8e-80f6-a510-c76c6c1be9f2\\">Node API\uac00 \ubb34\uc5c7\uc774\uace0, React Native\uc5d0\uc11c Node-API \ubaa8\ub4c8\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"256e548d-8a8e-80da-baeb-e7ecef4f8cd1\\" id=\\"256e548d-8a8e-80da-baeb-e7ecef4f8cd1\\">Anchor positioning API \uc18c\uac1c \uae00</h2><a href=\\"https://webkit.org/blog/17240/a-gentle-introduction-to-anchor-positioning/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/17240/a-gentle-introduction-to-anchor-positioning/</a><h1 data-notion-block-id=\\"256e548d-8a8e-80fe-8fc0-e995a9f122f8\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://www.builder.io/blog/best-react-calendar-component-ai\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/best-react-calendar-component-ai</a><p data-notion-block-id=\\"259e548d-8a8e-8097-a259-ce19ad306694\\">\uc5b4\ub5a4 \uce98\ub9b0\ub354\uac00 \uc88b\uc744\uae4c, \uadf8\ub9ac\uace0 AI\uac00 \uc798 \ub2e4\ub8e8\ub294 \uce98\ub9b0\ub354\ub294 \ubb34\uc5c7\uc77c\uae4c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://2025.stateofcss.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2025.stateofcss.com/</a><p data-notion-block-id=\\"256e548d-8a8e-8060-a92f-cfa831e05359\\">State of CSS 2025 \uacb0\uacfc\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4! \ucd5c\uc2e0 CSS\uc5d0\uc11c\ubd80\ud130 CSS \uc0ac\uc6a9 \ub3d9\ud5a5\uae4c\uc9c0 \uc54c\uc544\ubcf4\uc138\uc694.</p><a href=\\"https://nextjs.org/blog/next-15-5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15-5</a><p data-notion-block-id=\\"25ce548d-8a8e-8080-b896-d49c34116c54\\">Next.js 15.5\uc758 \ucd9c\uc2dc\ub85c Turbopack \ube4c\ub4dc\uac00 \ubca0\ud0c0 \ubc84\uc804\uc774 \ub418\uace0, Node.js middleware\uac00 \uc548\uc815\ud654\ub41c \uac83\uc744 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.callstack.com/blog/react-native-enterprise-framework-is-now-rock\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/react-native-enterprise-framework-is-now-rock</a><p data-notion-block-id=\\"256e548d-8a8e-80ca-9f6c-fb154590d246\\">Callstack\uc5d0\uc11c \ub9cc\ub4dc\ub294 RNEF \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc774\ub984\uc774 Rock\uc73c\ub85c \ubc14\ub010\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://shopify.engineering/flashlist-v2\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/flashlist-v2</a><p data-notion-block-id=\\"25ce548d-8a8e-80da-bd1c-d757a6c651c1\\">React Native\uc5d0\uc11c\uc758 \ube60\ub978 \ub9ac\uc2a4\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\uc778 FlashList\uac00 New Architecture\ub97c \uc704\ud574 \uc7ac\uc791\uc131\uc744 \ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"256e548d-8a8e-8056-86a4-d2263420144b\\" id=\\"256e548d-8a8e-8056-86a4-d2263420144b\\">\ubc88\uc678: Lambda\uc758 Cold Start \uce21\uc815\ud558\uae30</h2><a href=\\"https://goose.icu/lambda/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://goose.icu/lambda/</a><p data-notion-block-id=\\"25ce548d-8a8e-8068-8fed-f4f2e0f7a73f\\">Node, LLRT, \uadf8\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \ucef4\ud30c\uc77c\ud0c0\uc784 JS\uc778 Proffor\uc758 Cold Start \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"259e548d-8a8e-8046-8cf4-f01cff20644c\\" id=\\"259e548d-8a8e-8046-8cf4-f01cff20644c\\">\ubc88\uc678: \uc88b\uc740 \uc2dc\uc2a4\ud15c \ub514\uc790\uc778\uc740 \ubb34\uc5c7\uc77c\uae4c</h2><a href=\\"https://www.seangoedecke.com/good-system-design/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.seangoedecke.com/good-system-design/</a><p data-notion-block-id=\\"25ce548d-8a8e-802f-b200-d4d55da1fb09\\">\uc5ec\ub7ec\uac00\uc9c0 \uc2dc\uc2a4\ud15c \ub514\uc790\uc778\uc5d0 \ub300\ud55c \ud301\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5b8\uc81c\ub098 \uc88b\uc740 \uc2dc\uc2a4\ud15c \ub514\uc790\uc778\uc740 \uc0c1\ud669\uc5d0 \ub530\ub77c \ubc14\ub00c\uae30 \ub54c\ubb38\uc5d0, \ud301\uc815\ub3c4\ub85c \uc54c\uace0 \ub118\uc5b4\uac00\uba74 \uc88b\uaca0\ub124\uc694 \ud83d\ude42</p>"}')}}]);